import React, { useState, useEffect } from 'react';

export default function ChapterIntroSpread({ onContinue, onBack }) {
  const [currentPage, setCurrentPage] = useState(1);
  const TOTAL_PAGES = 5;

  const showPage = (n) => {
    setCurrentPage(n);
  };

  const goNext = () => {
    if (currentPage < TOTAL_PAGES) {
      showPage(currentPage + 1);
    } else if (currentPage === TOTAL_PAGES) {
      onContinue();
    }
  };

  const goPrev = () => {
    if (currentPage > 1) {
      showPage(currentPage - 1);
    } else if (currentPage === 1) {
      onBack();
    }
  };

  const goBackAction = () => {
    onBack();
  };

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') goNext();
      if (e.key === 'ArrowLeft') goPrev();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [currentPage, onContinue, onBack]);

  return (
    <div className="slogan-stage">
      <style>{`
  * { box-sizing: border-box; }
  .slogan-stage {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 10000;
    margin: 0;
    padding: 0;
    width: 100vw;
    height: 100vh;
    background: transparent;
    overflow: hidden;
    font-family: Georgia, 'Times New Roman', serif;
  }

  .stage-inner {
    width: 100vw;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .page-frame {
    position: relative;
    display: none;
    width: 100vw;
    height: 100vh;
  }

  .page-frame.active {
    display: block;
  }

  .page-frame img {
    width: 100%;
    height: 100%;
    display: block;
    user-select: none;
    -webkit-user-drag: none;
    pointer-events: none;
  }

  .nav-btn {
    position: absolute;
    background: transparent;
    border: none;
    cursor: pointer;
    padding: 0;
    margin: 0;
  }

  .nav-btn:disabled {
    cursor: default;
  }

  .nav-btn:not(:disabled):hover {
    background: rgba(255, 255, 255, 0.08);
    border-radius: 6px;
  }

  .nav-btn:not(:disabled):active {
    background: rgba(0, 0, 0, 0.10);
  }
`}</style>
      <div className="stage-inner">

        <div className={`page-frame ${currentPage === 1 ? 'active' : ''}`} id="page1">
          <img src="data:image/webp;base64," alt="Page 1 of 5" />
          <button className="nav-btn" onClick={goBackAction} style={{ left: '2.384%', top: '89.968%', width: '11.204%', height: '6.297%' }} aria-label="Back"></button>
          <button className="nav-btn" onClick={goPrev} style={{ left: '14.839%', top: '89.968%', width: '15.613%', height: '6.297%' }} aria-label="Previous Page"></button>
          <button className="nav-btn" onClick={goNext} style={{ left: '84.863%', top: '89.968%', width: '12.812%', height: '6.297%' }} aria-label="Next Page"></button>
        </div>

        <div className={`page-frame ${currentPage === 2 ? 'active' : ''}`} id="page2">
          <img src="data:image/webp;base64," alt="Page 2 of 5" />
          <button className="nav-btn" onClick={goBackAction} style={{ left: '2.443%', top: '90.181%', width: '8.94%', height: '6.19%' }} aria-label="Back"></button>
          <button className="nav-btn" onClick={goPrev} style={{ left: '12.515%', top: '90.181%', width: '14.541%', height: '6.19%' }} aria-label="Previous Page"></button>
          <button className="nav-btn" onClick={goNext} style={{ left: '85.399%', top: '90.181%', width: '12.098%', height: '6.19%' }} aria-label="Next Page"></button>
        </div>

        <div className={`page-frame ${currentPage === 3 ? 'active' : ''}`} id="page3">
          <img src="data:image/webp;base64," alt="Page 3 of 5" />
          <button className="nav-btn" onClick={goBackAction} style={{ left: '2.384%', top: '90.181%', width: '8.999%', height: '6.083%' }} aria-label="Back"></button>
          <button className="nav-btn" onClick={goPrev} style={{ left: '12.455%', top: '90.181%', width: '14.601%', height: '6.083%' }} aria-label="Previous Page"></button>
          <button className="nav-btn" onClick={goNext} style={{ left: '85.339%', top: '90.181%', width: '12.157%', height: '6.083%' }} aria-label="Next Page"></button>
        </div>

        <div className={`page-frame ${currentPage === 4 ? 'active' : ''}`} id="page4">
          <img src="data:image/webp;base64," alt="Page 4 of 5" />
          <button className="nav-btn" onClick={goBackAction} style={{ left: '2.443%', top: '89.435%', width: '8.999%', height: '6.083%' }} aria-label="Back"></button>
          <button className="nav-btn" onClick={goPrev} style={{ left: '12.515%', top: '89.435%', width: '14.303%', height: '6.083%' }} aria-label="Previous Page"></button>
          <button className="nav-btn" onClick={goNext} style={{ left: '85.339%', top: '89.435%', width: '11.978%', height: '6.083%' }} aria-label="Next Page"></button>
        </div>

        <div className={`page-frame ${currentPage === 5 ? 'active' : ''}`} id="page5">
          <img src="data:image/webp;base64," alt="Page 5 of 5" />
          <button className="nav-btn" onClick={goBackAction} style={{ left: '2.524%', top: '88.911%', width: '9.211%', height: '5.444%' }} aria-label="Back"></button>
          <button className="nav-btn" onClick={goPrev} style={{ left: '12.934%', top: '88.911%', width: '15.079%', height: '5.444%' }} aria-label="Previous Page"></button>
          <button className="nav-btn" onClick={goNext} style={{ left: '85.931%', top: '88.911%', width: '11.798%', height: '5.444%' }} aria-label="Next Page"></button>
        </div>

      </div>
    </div>
  );
}
